package jp.co.aplink.seikyu;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.math.*;
import java.time.*;
import java.util.*;
import java.util.stream.*;

/** Source-based domain rules. Unanswered legacy rules fail explicitly. */
public class Domain {
 private final ObjectMapper m;
 public Domain(ObjectMapper mapper){m=mapper;}
 public static class Invalid extends RuntimeException{public Invalid(String message){super(message);}}
 static void require(boolean condition,String message){if(!condition)throw new Invalid(message);}
 ObjectNode obj(){return m.createObjectNode();}
 ArrayNode rows(ObjectNode s,String key){return (ArrayNode)s.get(key);}
 List<ObjectNode> list(ObjectNode s,String key){var out=new ArrayList<ObjectNode>();rows(s,key).forEach(x->out.add((ObjectNode)x));return out;}
 String text(JsonNode p,String key){return p.path(key).asText("").trim();}
 String need(JsonNode p,String key,String label){String v=text(p,key);require(!v.isEmpty()&&v.length()<=500,label+"を入力してください");return v;}
 long yen(JsonNode p,String key){String v=text(p,key);if(v.isBlank())return 0;require(v.matches("\\d{1,13}"),key+"は0以上の整数です");long n=Long.parseLong(v);require(n<=1000000000000L,"金額が上限を超えています");return n;}
 BigDecimal decimal(JsonNode p,String key){String v=text(p,key);require(v.matches("-?\\d{1,10}(\\.\\d{1,4})?"),key+"は小数4桁以内です");return new BigDecimal(v);}
 public static long amount(String q,String p){return new BigDecimal(q).multiply(new BigDecimal(p)).setScale(0,RoundingMode.DOWN).longValueExact();}
 static long tax(long net,int rate){return BigDecimal.valueOf(net).multiply(BigDecimal.valueOf(rate)).divide(BigDecimal.valueOf(100),0,RoundingMode.DOWN).longValueExact();}
 LocalDate date(String v){try{require(v.matches("\\d{4}-\\d{2}-\\d{2}"),"日付が不正です");return LocalDate.parse(v);}catch(DateTimeException e){throw new Invalid("日付が不正です");}}
 public static LocalDate[] period(String month,int closing){try{require(month.matches("\\d{4}-\\d{2}"),"年月が不正です");YearMonth ym=YearMonth.parse(month);require(ym.getYear()>=2000&&ym.getYear()<=2100,"年月が範囲外です");require(closing>=1&&(closing<=28||closing==31),"締日は1〜28または31(月末)です");YearMonth prev=ym.minusMonths(1);return new LocalDate[]{prev.atDay(Math.min(closing,prev.lengthOfMonth())).plusDays(1),ym.atDay(Math.min(closing,ym.lengthOfMonth()))};}catch(DateTimeException e){throw new Invalid("年月が不正です");}}
 void open(ObjectNode s,String day){date(day);require(StreamSupport.stream(rows(s,"closed").spliterator(),false).noneMatch(x->day.startsWith(x.asText())),"確定済み月は変更できません");}
 String id(ObjectNode s,String prefix){int n=s.path("seq").asInt()+1;s.put("seq",n);return prefix+String.format("%06d",n);}
 ObjectNode find(ObjectNode s,String collection,String key){return list(s,collection).stream().filter(x->text(x,"id").equals(key)).findFirst().orElseThrow(()->new Invalid("対象が見つかりません: "+collection));}
 public ObjectNode fresh(){var s=obj();s.put("schemaVersion",1).put("seq",0);for(String k:List.of("customers","vendors","items","banks","accounts","subaccounts","shipments","invoices","receipts","purchases","inventory","payables","cash","payments","journals","closed","advances"))s.putArray(k);s.putObject("settings").put("company","APLink 請求管理").put("department","063");return s;}
 ObjectNode line(String side,String account,long amount){return obj().put("side",side).put("account",account).put("amount",amount);}
 void journal(ObjectNode s,String source,String day,String pattern,List<ObjectNode> all){var ls=all.stream().filter(x->x.path("amount").asLong()!=0).toList();long debit=0,credit=0;for(var l:ls){long value=l.path("amount").asLong();require(value>0,"仕訳金額が不正です");if(text(l,"side").equals("D"))debit+=value;else credit+=value;}require(debit==credit&&debit>0,"仕訳の貸借が一致しません");require(list(s,"journals").stream().noneMatch(x->text(x,"source").equals(source)),"仕訳は作成済みです");var j=obj().put("id",id(s,"J")).put("source",source).put("date",day).put("pattern",pattern).put("total",debit);j.set("lines",m.valueToTree(ls));rows(s,"journals").add(j);}
 public JsonNode execute(ObjectNode s,String action,JsonNode p){return switch(action){
  case "master.save"->saveMaster(s,p);
  case "master.import"->importMasters(s,p);
  case "shipment.save"->shipment(s,p);
  case "billing.create"->billing(s,p);
  case "invoice.issue"->issue(s,p);
  case "receipt.create"->receipt(s,p);
  case "purchase.create"->purchase(s,p);
  case "payable.create","cash.create"->expense(s,p,action);
  case "payment.create"->payment(s,p);
  case "inventory.save"->inventory(s,p);
  case "month.close"->close(s,p);
  default->throw new Invalid("対応していない操作です");
 };}
 ObjectNode saveMaster(ObjectNode s,JsonNode p){String kind=text(p,"kind");require(List.of("customers","vendors","items","banks","accounts","subaccounts").contains(kind),"マスタ種別が不正です");String code=need(p,"code","コード"),name=need(p,"name","名称"),key=text(p,"id");require(list(s,kind).stream().noneMatch(x->text(x,"code").equals(code)&&!text(x,"id").equals(key)),"コードが重複しています");var old=key.isEmpty()?null:find(s,kind,key);var r=obj().put("id",key.isEmpty()?id(s,"M"):key).put("code",code).put("name",name).put("active",!p.path("active").asText().equals("false"));
  if(kind.equals("customers")){int closing=p.path("closing").asInt(20);period("2026-01",closing);r.put("closing",closing);long opening=yen(p,"opening");require(opening==0,"開始売掛残高は移行照合後に取り込んでください");r.put("opening",opening);}
  if(kind.equals("items")){int rate=p.path("taxRate").asInt(10);require(List.of(0,8,10).contains(rate),"税率が不正です");r.put("taxRate",rate).put("price",yen(p,"price")).put("unit",text(p,"unit").isEmpty()?"t":text(p,"unit"));}
  if(kind.equals("vendors"))for(String field:List.of("bank","branch","account","kana"))r.put(field,text(p,field));
  if(old==null)rows(s,kind).add(r);else{for(int i=0;i<rows(s,kind).size();i++)if(rows(s,kind).get(i)==old)rows(s,kind).set(i,r);}return obj().put("id",text(r,"id"));
 }
 JsonNode importMasters(ObjectNode s,JsonNode p){require(p.path("rows").isArray()&&p.path("rows").size()>0&&p.path("rows").size()<=2000,"取込は1〜2000件です");for(JsonNode row:p.path("rows")){require(row.isObject(),"CSV行が不正です");ObjectNode value=row.deepCopy();value.put("kind",text(p,"kind"));saveMaster(s,value);}return obj().put("count",p.path("rows").size());}
 JsonNode shipment(ObjectNode s,JsonNode p){String day=need(p,"date","出荷日");open(s,day);var customer=find(s,"customers",text(p,"customerId"));var item=find(s,"items",text(p,"itemId"));require(customer.path("active").asBoolean()&&item.path("active").asBoolean(),"無効なマスタです");BigDecimal q=decimal(p,"quantity"),price=decimal(p,"price");require(q.signum()!=0&&price.signum()>=0,"数量・単価が不正です");long net=amount(q.toPlainString(),price.toPlainString());require(Math.abs(net)<=1000000000000L,"金額が上限を超えています");String key=text(p,"id"),method=text(p,"method");if(method.isEmpty())method="credit";require(List.of("credit","cash","card").contains(method),"売上区分が不正です");var r=obj().put("id",key.isEmpty()?id(s,"S"):key).put("date",day).put("customerId",text(p,"customerId")).put("itemId",text(p,"itemId")).put("site",text(p,"site")).put("quantity",q.toPlainString()).put("price",price.toPlainString()).put("net",net).put("taxRate",item.path("taxRate").asInt()).put("method",method).put("invoiceId","");
  if(key.isEmpty())rows(s,"shipments").add(r);else{var old=find(s,"shipments",key);open(s,text(old,"date"));require(text(old,"invoiceId").isBlank(),"請求済み伝票は変更できません");for(int i=0;i<rows(s,"shipments").size();i++)if(rows(s,"shipments").get(i)==old)rows(s,"shipments").set(i,r);}return obj().put("id",text(r,"id"));
 }
 JsonNode billing(ObjectNode s,JsonNode p){int closing=p.path("closing").asInt();var range=period(text(p,"month"),closing);String start=range[0].toString(),end=range[1].toString();open(s,end);require(p.path("customerIds").isArray()&&!p.path("customerIds").isEmpty(),"得意先を選択してください");var keys=new LinkedHashSet<String>();p.path("customerIds").forEach(x->keys.add(x.asText()));int count=0;
  for(String key:keys){var c=find(s,"customers",key);require(c.path("closing").asInt()==closing,"得意先の締日が一致しません");require(list(s,"invoices").stream().noneMatch(i->text(i,"customerId").equals(key)&&text(i,"end").equals(end)),"同じ締日の請求は作成済みです");var sales=list(s,"shipments").stream().filter(x->text(x,"customerId").equals(key)&&text(x,"invoiceId").isBlank()&&text(x,"date").compareTo(start)>=0&&text(x,"date").compareTo(end)<=0).toList();if(sales.isEmpty())continue;require(sales.stream().allMatch(x->text(x,"method").equals("credit")),"現金・カード売上は処理方式の確認待ちです (Q16/Q17)");require(sales.stream().allMatch(x->x.path("net").asLong()>=0),"マイナス売上の税・仕訳方式は確認待ちです (Q18)");long net=0,vat=0;for(int rate:List.of(0,8,10)){long subtotal=sales.stream().filter(x->x.path("taxRate").asInt()==rate).mapToLong(x->x.path("net").asLong()).sum();net+=subtotal;vat+=tax(subtotal,rate);}require(net+vat>0,"請求額が0です");String invId=id(s,"I");var inv=obj().put("id",invId).put("customerId",key).put("start",start).put("end",end).put("net",net).put("tax",vat).put("total",net+vat).put("paid",0).put("issued",0);inv.put("customerName",text(c,"name")).put("company",s.path("settings").path("company").asText());var detail=inv.putArray("lines");for(var sale:sales){var copy=sale.deepCopy();copy.put("itemName",text(find(s,"items",text(sale,"itemId")),"name"));detail.add(copy);}rows(s,"invoices").add(inv);sales.forEach(x->x.put("invoiceId",invId));journal(s,invId,end,"A01",List.of(line("D","1131",net+vat).put("customerId",key),line("C","8130",net).put("department","063"),line("C","4415",vat)));count++;}
  require(count>0,"対象となる未請求の出荷がありません");return obj().put("count",count);
 }
 JsonNode issue(ObjectNode s,JsonNode p){require(p.path("ids").isArray()&&!p.path("ids").isEmpty(),"請求書を選択してください");var keys=new LinkedHashSet<String>();p.path("ids").forEach(x->keys.add(x.asText()));for(String key:keys){var inv=find(s,"invoices",key);inv.put("issued",inv.path("issued").asInt()+1).put("lastIssued",Instant.now().toString());}return obj().put("count",keys.size());}
 JsonNode receipt(ObjectNode s,JsonNode p){String day=need(p,"date","入金日"),customer=text(p,"customerId");open(s,day);find(s,"customers",customer);var amounts=new LinkedHashMap<String,Long>();for(String k:List.of("bank","cash","fee","discount","notes","advance","cooperation"))amounts.put(k,yen(p,k));require(amounts.get("cooperation")==0,"協力会費の税区分は確認待ちです (Q04)");require(amounts.get("advance")==0,"預り金の開始残高・受入履歴は確認待ちです (Q10)");long total=amounts.values().stream().mapToLong(Long::longValue).sum();require(total>0,"入金額を入力してください");require(p.path("allocations").isArray()&&!p.path("allocations").isEmpty(),"消込対象を選択してください");long allocated=0;var seen=new HashSet<String>();var lines=new ArrayList<ObjectNode>();
  for(JsonNode a:p.path("allocations")){String key=text(a,"invoiceId");require(seen.add(key),"消込対象が重複しています");var inv=find(s,"invoices",key);require(text(inv,"customerId").equals(customer),"異なる得意先には消込できません");require(inv.path("issued").asInt()>0,"請求書発行後に消込できます");require(day.compareTo(text(inv,"end"))>=0,"入金日が締日より前です");long value=yen(a,"amount"),paid=inv.path("paid").asLong();require(value>0&&value<=inv.path("total").asLong()-paid,"入金額が請求残高を超えています");inv.put("paid",paid+value);allocated+=value;lines.add(line("C","1131",value).put("customerId",customer).put("closing",text(inv,"end")));}
  require(allocated==total,"入金合計と消込合計が一致しません");var r=obj().put("id",id(s,"R")).put("date",day).put("customerId",customer).put("total",total);amounts.forEach(r::put);r.set("allocations",p.path("allocations").deepCopy());rows(s,"receipts").add(r);lines.add(line("D","1112",amounts.get("bank")).put("bankCode",text(p,"bankCode")));lines.add(line("D","1111",amounts.get("cash")));lines.add(line("D","8330",amounts.get("fee")).put("subaccount","101"));lines.add(line("D","8850",amounts.get("discount")));lines.add(line("D","1120",amounts.get("notes")));journal(s,text(r,"id"),day,"B01",lines);return obj().put("id",text(r,"id"));
 }
 JsonNode purchase(ObjectNode s,JsonNode p){String day=need(p,"date","仕入日");open(s,day);find(s,"vendors",text(p,"vendorId"));find(s,"items",text(p,"itemId"));BigDecimal q=decimal(p,"quantity"),price=decimal(p,"price");require(q.signum()>0&&price.signum()>0,"数量・単価は正数です");var r=obj().put("id",id(s,"P")).put("date",day).put("vendorId",text(p,"vendorId")).put("itemId",text(p,"itemId")).put("quantity",q.toPlainString()).put("price",price.toPlainString()).put("net",amount(q.toPlainString(),price.toPlainString())).put("memo",text(p,"memo"));rows(s,"purchases").add(r);return obj().put("id",text(r,"id"));}
 JsonNode expense(ObjectNode s,JsonNode p,String action){String day=need(p,"date","日付"),account=need(p,"account","費用科目");open(s,day);boolean payable=action.equals("payable.create");if(payable)find(s,"vendors",text(p,"vendorId"));require(list(s,"accounts").stream().anyMatch(x->text(x,"code").equals(account)&&x.path("active").asBoolean()),"勘定科目をマスタ登録してください");long value=yen(p,"amount");require(value>0,"金額を入力してください");String memo=need(p,"memo","摘要"),taxCode=need(p,"taxCode","税区分");var r=obj().put("id",id(s,payable?"B":"C")).put("date",day).put("vendorId",text(p,"vendorId")).put("account",account).put("subaccount",text(p,"subaccount")).put("taxCode",taxCode).put("department",text(p,"department")).put("amount",value).put("paid",0).put("memo",memo);rows(s,payable?"payables":"cash").add(r);journal(s,text(r,"id"),day,payable?"D01":"E01",List.of(line("D",account,value).put("subaccount",text(p,"subaccount")).put("taxCode",taxCode).put("department",text(p,"department")).put("memo",memo),line("C",payable?"4121":"1111",value)));return obj().put("id",text(r,"id"));}
 JsonNode payment(ObjectNode s,JsonNode p){String day=need(p,"date","支払日");open(s,day);var bill=find(s,"payables",text(p,"payableId"));long value=yen(p,"amount"),paid=bill.path("paid").asLong();require(value>0&&value<=bill.path("amount").asLong()-paid,"支払額が未払残高を超えています");require(day.compareTo(text(bill,"date"))>=0,"支払日が請求日より前です");require(yen(p,"fee")==0&&yen(p,"offset")==0,"手数料・相殺ルールは確認待ちです (Q03/Q08)");bill.put("paid",paid+value);var r=obj().put("id",id(s,"T")).put("date",day).put("vendorId",text(bill,"vendorId")).put("payableId",text(bill,"id")).put("amount",value).put("bankCode",text(p,"bankCode"));rows(s,"payments").add(r);journal(s,text(r,"id"),day,"F01",List.of(line("D","4121",value),line("C","1112",value).put("bankCode",text(p,"bankCode"))));return obj().put("id",text(r,"id"));}
 JsonNode inventory(ObjectNode s,JsonNode p){String month=text(p,"month"),item=text(p,"itemId"),end=period(month,20)[1].toString();open(s,end);find(s,"items",item);var existing=list(s,"inventory").stream().filter(x->text(x,"itemId").equals(item)).toList();require(existing.stream().noneMatch(x->text(x,"month").compareTo(month)>=0),"当月または後月の在庫は登録済みです");long previous=existing.stream().max(Comparator.comparing(x->text(x,"month"))).map(x->x.path("value").asLong()).orElse(0L);BigDecimal q=decimal(p,"quantity"),price=decimal(p,"price");require(q.signum()>=0&&price.signum()>=0,"在庫・評価単価は0以上です");long value=amount(q.toPlainString(),price.toPlainString());var r=obj().put("id",id(s,"V")).put("month",month).put("itemId",item).put("quantity",q.toPlainString()).put("price",price.toPlainString()).put("value",value).put("previous",previous);rows(s,"inventory").add(r);if(value+previous>0)journal(s,text(r,"id"),end,"C01",List.of(line("D","82316",previous),line("C","1360",previous),line("D","1360",value),line("C","82316",value)));return obj().put("id",text(r,"id"));}
 JsonNode close(ObjectNode s,JsonNode p){String month=text(p,"month");period(month,20);require(StreamSupport.stream(rows(s,"closed").spliterator(),false).noneMatch(x->x.asText().equals(month)),"確定済みです");require(list(s,"shipments").stream().noneMatch(x->text(x,"date").startsWith(month)&&text(x,"invoiceId").isEmpty()),"未請求の出荷があります");rows(s,"closed").add(month);return obj().put("month",month);}
}
